// Product arena art contract (ACTION-ART-01B). Pure presentation constants; must not import Phaser.
// The runtime background and dohyo overlay are generated by tools/dohyo_art (accepted Candidate C) in a
// 1920x1080 art space whose ring is centered on the canvas. The Simulation stays the gameplay source of
// truth; this only maps Simulation meters onto that fixed art space.
import type { ArenaSetup, Vec2 } from '../sumo/BoutTypes.ts'

// Logical canvas = runtime art space (1:1, no resampling inside Phaser).
export const PRODUCT_ART_WIDTH = 1920
export const PRODUCT_ART_HEIGHT = 1080
// Art pixel of the Simulation origin (ring center).
export const PRODUCT_ART_CENTER: Vec2 = { x: PRODUCT_ART_WIDTH / 2, y: PRODUCT_ART_HEIGHT / 2 }
// Base gameplay radius (normal tawara outer edge) in the runtime art.
export const PRODUCT_RING_RADIUS_PX = 400
// Tokudawara drawn into the overlay (runtime px / radians); the Simulation values must match.
export const PRODUCT_TOKUDAWARA_DEPTH_PX = 21
export const PRODUCT_TOKUDAWARA_HALF_ANGLE = Math.PI / 20

// Simulation meters -> art px: the Simulation ring radius lands exactly on the art ring radius.
export function productPixelsPerMeter(arena: ArenaSetup): number {
  return PRODUCT_RING_RADIUS_PX / arena.radius
}
